// Validates one registry entry against the Section 9 schema shape this
// module encodes. Returns { valid: boolean, errors: string[] }.
function validateRegistryEntry(entry) {
  const errors = [];
  if (!entry || typeof entry !== 'object') return { valid: false, errors: ['entry is not an object'] };

  const requireString = (path, v, minLen) => {
    if (typeof v !== 'string' || v.trim().length < (minLen || 1)) errors.push(path + ' missing or under ' + (minLen || 1) + ' chars');
  };

  requireString('axisId', entry.axisId);
  requireString('displayName', entry.displayName);
  requireString('centralQuestion', entry.centralQuestion, 20);
  requireString('shortDefinition', entry.shortDefinition, 40);
  requireString('expandedDefinition', entry.expandedDefinition, 150);
  requireString('commonMisconception', entry.commonMisconception, 40);
  requireString('relatedAxes', entry.relatedAxes, 20);
  requireString('conceptualGroup', entry.conceptualGroup);
  requireString('reflectionPrompt', entry.reflectionPrompt, 30);
  requireString('methodNote', entry.methodNote, 40);

  for (const pole of ['L', 'R']) {
    const p = entry.poles && entry.poles[pole];
    if (!p) { errors.push('poles.' + pole + ' missing'); continue; }
    requireString('poles.' + pole + '.name', p.name);
    requireString('poles.' + pole + '.shortDef', p.shortDef, 20);
    requireString('poles.' + pole + '.expandedDef', p.expandedDef, 60);
  }

  for (const band of BAND_KEYS) {
    const b = entry.bands && entry.bands[band];
    if (!b) { errors.push('bands.' + band + ' missing'); continue; }
    requireString('bands.' + band + '.full', b.full, 300);
    requireString('bands.' + band + '.short', b.short, 80);
    const expected = BAND_THRESHOLDS[band];
    if (!Array.isArray(b.range) || b.range[0] !== expected[0] || b.range[1] !== expected[1]) {
      errors.push('bands.' + band + '.range does not match BAND_THRESHOLDS');
    }
  }

  for (const k of MIDPOINT_VARIANT_KEYS) {
    requireString('midpointVariants.' + k, entry.midpointVariants && entry.midpointVariants[k], 40);
  }

  // Dash and score-descriptor hygiene (content standard Part I).
  const em = String.fromCharCode(0x2014), en = String.fromCharCode(0x2013);
  const walk = (v, path) => {
    if (typeof v === 'string') {
      if (v.includes(em) || v.includes(en)) errors.push(path + ' contains an em/en dash');
      if (/confidence score/i.test(v)) errors.push(path + ' uses banned "confidence score" phrasing');
    } else if (v && typeof v === 'object') {
      for (const k of Object.keys(v)) walk(v[k], path + '.' + k);
    }
  };
  walk(entry, entry.axisId || 'entry');

  return { valid: errors.length === 0, errors };
}

module.exports = {
  REGISTRY_SCHEMA_VERSION,
  BAND_THRESHOLDS,
  BAND_KEYS,
  MIDPOINT_VARIANT_KEYS,
  REVIEW_STATUS,
  BELIEF_MAP_REGISTRY,
  validateRegistryEntry,
};
